import { test, expect } from '@playwright/test';

test.describe('Date Picker - Past Date Prevention', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/booking');
  });

  test('should prevent selecting past dates and only allow future dates', async ({ page }) => {
    // Get the date picker input using getByLabel
    const dateInput = page.getByLabel('Booking Date');
    await expect(dateInput).toBeVisible();

    // Click the date input to open the calendar
    await dateInput.click();

    // Get the calendar container using getByRole
    const calendar = page.getByRole('dialog', { name: /calendar/i });
    await expect(calendar).toBeVisible();

    // Get the calendar grid using getByRole
    const calendarGrid = page.getByRole('grid');
    await expect(calendarGrid).toBeVisible();

    // Get the first day of the month (should be a past date)
    const firstDay = page.getByText('1');
    await expect(firstDay).toBeVisible();

    // Attempt to click the first day (past date)
    await firstDay.click();

    // Verify the date input does not update
    await expect(dateInput).toHaveValue('');

    // Get the last day of the month (should be a future date)
    const lastDay = page.getByText('31');
    await expect(lastDay).toBeVisible();

    // Click the last day (future date)
    await lastDay.click();

    // Verify the date input updates to the future date
    await expect(dateInput).toHaveValue('2024-12-31');

    // Verify the date is highlighted
    const selectedDate = page.getByText('31');
    await expect(selectedDate).toHaveClass(/selected-date/);

    // Verify the calendar closes
    await expect(calendar).not.toBeVisible();
  });

  test('should display error message when attempting to submit with past date', async ({ page }) => {
    // Get the date picker input using getByLabel
    const dateInput = page.getByLabel('Booking Date');
    await expect(dateInput).toBeVisible();

    // Click the date input to open the calendar
    await dateInput.click();

    // Get the calendar grid using getByRole
    const calendarGrid = page.getByRole('grid');
    await expect(calendarGrid).toBeVisible();

    // Get the first day of the month (past date)
    const firstDay = page.getByText('1');
    await firstDay.click();

    // Verify the date input updates to the past date
    await expect(dateInput).toHaveValue('2024-10-01');

    // Close the calendar
    await page.getByRole('button', { name: /close/i }).click();

    // Get the submit button using getByRole
    const submitButton = page.getByRole('button', { name: /submit/i });
    await expect(submitButton).toBeVisible();

    // Attempt to submit the form
    await submitButton.click();

    // Verify error message appears
    const errorMessage = page.getByText(/past date/i);
    await expect(errorMessage).toBeVisible();

    // Verify date input still contains the past date
    await expect(dateInput).toHaveValue('2022-01-01');

    // Verify form is not submitted
    await expect(page).not.toHaveURL(/success/);
  });
});
